"use client";

import Image from "next/image";
import { motion, useMotionValue, useSpring, useTransform } from "motion/react";
import type { Box } from "@/data/site";

type Screen = { src: string; alt: string; box: Box };

/**
 * 复古设备线稿 + 屏幕里的作品画面。
 * 鼠标移动时整体轻微 3D 倾斜，屏幕画面带扫描线，悬停时画面变亮。
 */
export default function DeviceFrame({
  device,
  screens,
  sizes,
  priority = false,
}: {
  device: { src: string; alt: string; aspect: [number, number] };
  screens: Screen[];
  sizes: string;
  priority?: boolean;
}) {
  const mx = useMotionValue(0.5);
  const my = useMotionValue(0.5);
  const rotateX = useSpring(useTransform(my, [0, 1], [6, -6]), { stiffness: 150, damping: 18 });
  const rotateY = useSpring(useTransform(mx, [0, 1], [-8, 8]), { stiffness: 150, damping: 18 });

  return (
    <motion.div
      onMouseMove={(e) => {
        const r = e.currentTarget.getBoundingClientRect();
        mx.set((e.clientX - r.left) / r.width);
        my.set((e.clientY - r.top) / r.height);
      }}
      onMouseLeave={() => {
        mx.set(0.5);
        my.set(0.5);
      }}
      style={{ rotateX, rotateY, transformPerspective: 1000, aspectRatio: `${device.aspect[0]} / ${device.aspect[1]}` }}
      className="group relative w-full"
    >
      <Image src={device.src} alt={device.alt} fill sizes={sizes} priority={priority} className="object-contain" />
      {screens.map((s) => (
        <div
          key={s.src}
          className="scanlines absolute overflow-hidden"
          style={{
            left: `${s.box.left}%`,
            top: `${s.box.top}%`,
            width: `${s.box.width}%`,
            height: `${s.box.height}%`,
          }}
        >
          <Image
            src={s.src}
            alt={s.alt}
            fill
            sizes={sizes}
            priority={priority}
            className="object-cover brightness-90 transition duration-500 group-hover:scale-105 group-hover:brightness-110"
          />
        </div>
      ))}
    </motion.div>
  );
}
